 useEffect(()=>{setLang(localStorage.getItem('paisa-lang')==='hi'?'hi':'en');setDetailed(localStorage.getItem('paisa-detail')==='true');},[]);
 useEffect(()=>{document.documentElement.lang=lang;localStorage.setItem('paisa-lang',lang);},[lang]);
 useEffect(()=>{localStorage.setItem('paisa-detail',String(detailed));},[detailed]);
